    case 'title-asc':
      return (a, b) => String(a.title).toLowerCase().localeCompare(String(b.title).toLowerCase());
    case 'title-desc':
      return (a, b) => String(b.title).toLowerCase().localeCompare(String(a.title).toLowerCase());
    case 'added-desc':
    default:
      return (a, b) => b.createdAt - a.createdAt;
  }
