// Sorting (SCN-013). Options: date added (newest/oldest), recently updated,
// title A–Z / Z–A. "updated" reflects the last meaningful change to a bookmark.

export const SORT_MODES = [
  ['added-desc', 'Date added — newest first'],
  ['added-asc', 'Date added — oldest first'],
  ['updated-desc', 'Recently updated'],
  ['title-asc', 'Title — A to Z'],
  ['title-desc', 'Title — Z to A'],
];

export function comparator(mode) {
  switch (mode) {
    case 'added-asc':
      return (a, b) => a.createdAt - b.createdAt;
    case 'updated-desc':
      return (a, b) => (b.updatedAt || b.createdAt) - (a.updatedAt || a.createdAt);
    case 'title-asc':
      return (a, b) => String(a.title).toLowerCase().localeCompare(String(b.title).toLowerCase());
    case 'title-desc':
      return (a, b) => String(b.title).toLowerCase().localeCompare(String(a.title).toLowerCase());
    case 'added-desc':
    default:
      return (a, b) => b.createdAt - a.createdAt;
  }
}

export function sortItems(items, mode) {
  return items.slice().sort(comparator(mode));
}
// Tag normalisation (SCN-008): lowercased, leading '#' dropped, internal
// whitespace collapsed to single hyphens. The same normalised tag is never
// stored twice on one bookmark (callers de-duplicate).

export function normalizeTag(raw) {
  return String(raw || '')
    .trim()
    .replace(/^#+/, '')
    .toLowerCase()
    .replace(/\s+/g, '-');
}

export function addTag(tags, raw) {
  const t = normalizeTag(raw);
  if (!t) return tags.slice();
  return tags.indexOf(t) === -1 ? tags.concat([t]) : tags.slice();
}

export function removeTag(tags, raw) {
  const t = normalizeTag(raw);
  return tags.filter((x) => x !== t);
}
// URL handling: normalisation, validation, duplicate keys, PDF detection.
// Behaviour basis: SCN-001 (save), SCN-002 (duplicate rule), SCN-011 (invalid),
// SCN-016 (PDF detection).

export function normalizeUrl(raw) {
  const s = String(raw || '').trim();
  return /^https?:\/\//i.test(s) ? s : 'https://' + s;
}

export function hostOf(raw) {
  try {
    return new URL(normalizeUrl(raw)).hostname.replace(/^www\./i, '');
  } catch {
    return String(raw || '');
  }
}

// A plausible web address: parseable, host contains a dot, no whitespace in host.
export function isValidUrl(raw) {
  try {
    const u = new URL(normalizeUrl(raw));
    return u.hostname.indexOf('.') > 0 && !/\s/.test(u.hostname);
  } catch {
    return false;
  }
}

// Duplicate key (SCN-002): host is case-insensitive with a leading "www." and a
// trailing slash ignored; the path (and query) keep their original capitalisation.
export function dedupKey(raw) {
  try {
    const u = new URL(normalizeUrl(raw));
    const host = u.hostname.replace(/^www\./i, '').toLowerCase();
    const path = (u.pathname + (u.search || '')).replace(/\/$/, '');
    return host + path;
  } catch {
    return String(raw || '');
  }
}

// PDF links keep the PDF itself offline (SCN-016). Robust to ?query / #hash.
export function isPdf(raw) {
  return /\.pdf($|[?#])/i.test(String(raw || ''));
